import type { OpenApiContractSnapshot, OpenApiOperationSnapshot } from './openapi.js';

export interface GeneratedSdkArtifact {
  filename: string;
  content: string;
  operations: number;
}

export function generateSdkOperationMap(snapshot: OpenApiContractSnapshot): GeneratedSdkArtifact {
  const lines = [
    '/* Auto-generated by CajeerBots contracts. Do not edit manually. */',
    "export interface GeneratedApiOperation { method: string; path: string; operationId: string; tags: string[]; deprecated: boolean; secured: boolean; }",
    'export const generatedApiOperations: GeneratedApiOperation[] = [',
    ...snapshot.operations.map((operation) => `  ${JSON.stringify(operationToSerializable(operation))},`),
    '];',
    '',
    'export const generatedApiOperationIds = new Set(generatedApiOperations.map((operation) => operation.operationId));',
    '',
  ];
  return { filename: 'generated-api-operations.ts', content: `${lines.join('\n')}`, operations: snapshot.operations.length };
}

export function generateSdkClientChecklist(snapshot: OpenApiContractSnapshot): GeneratedSdkArtifact {
  const lines = [
    '# CajeerBots SDK coverage checklist',
    '',
    `Generated from OpenAPI ${snapshot.version} (${snapshot.sourceSha256}).`,
    '',
    '| Method | Path | operationId | Secured | Deprecated |',
    '|---|---|---|---|---|',
    ...snapshot.operations.map((operation) => `| ${operation.method.toUpperCase()} | \`${operation.path}\` | \`${operation.operationId}\` | ${operation.secured ? 'yes' : 'no'} | ${operation.deprecated ? 'yes' : 'no'} |`),
    '',
  ];
  return { filename: 'SDK_COVERAGE.md', content: lines.join('\n'), operations: snapshot.operations.length };
}

function operationToSerializable(operation: OpenApiOperationSnapshot): OpenApiOperationSnapshot {
  return {
    method: operation.method,
    path: operation.path,
    operationId: operation.operationId,
    tags: operation.tags,
    summary: operation.summary,
    deprecated: operation.deprecated,
    secured: operation.secured,
  };
}
